def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    error_count = 0
    rich_count = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            if prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))
            if prev.get('error'):
                error_count += 1

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, 21)

    opp_count = len(alive_opponents)
    scarcity = opp_count * WATER_REQ - supply

    max_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 2 or no_water >= 2:
        base = DAILY_SALARY * 0.96
    elif hp <= 4 or no_water >= 1:
        base = DAILY_SALARY * 0.78
    else:
        if scarcity >= WATER_REQ * 2:
            base = DAILY_SALARY * 0.72
        elif scarcity > 0:
            base = DAILY_SALARY * 0.58
        else:
            base = DAILY_SALARY * 0.42

    if prev_bids:
        target = max(base, avg_prev + 2, max_prev * 0.92)
        if max_prev >= DAILY_SALARY * 0.9 and hp > 4 and no_water == 0:
            target = min(target, DAILY_SALARY * 0.38)
    else:
        target = base

    target += min(desperate_count, 3) * 2.0
    target += min(rich_count, 2) * 1.5
    target -= min(error_count, 2) * 2.0

    if supply >= 23 and hp > 4 and no_water == 0:
        target *= 0.82
    elif supply <= 17:
        target *= 1.08

    if day >= 8:
        target *= 1.08

    reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    if budget < reserve_floor and hp > 3 and no_water == 0:
        target = min(target, DAILY_SALARY * 0.35)

    bid = max(0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # Base caps
    max_affordable = max(0.0, budget)
    # We never bid more than what could be useful given supply; also keep some budget for later.
    useful_cap = max(0.0, min(max_affordable, supply))

    # If we are already in danger, bid harder.
    critical = (hp <= 2.0) or (no_water_days >= 2)

    # Read yesterday's bids from previous_trace only.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If no info, choose a moderate bid.
    if not prev_bids:
        target = DAILY_SALARY * (0.75 if critical else 0.55)
        return min(useful_cap, target)

    highest_prev_bid = max(prev_bids)
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

    # Aggression inference:
    # - If someone bid very high relative to daily salary, they likely expect to win water.
    # - We respond with a competitive bid but avoid overpaying when our HP is fine.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.80:
        pressure = 0.8
    elif highest_prev_bid >= DAILY_SALARY * 0.60:
        pressure = 0.6
    elif avg_prev_bid >= DAILY_SALARY * 0.45:
        pressure = 0.4
    else:
        pressure = 0.2

    # Determine bid target.
    # When critical, bid close to pressure level; otherwise bid less.
    if critical:
        # Bid enough to likely beat them.
        target = min(useful_cap, max(highest_prev_bid + 1.0, DAILY_SALARY * (0.85 + 0.1 * pressure)))
    else:
        # If opponents were aggressive, we still bid to avoid losing HP.
        if pressure >= 0.8:
            target = min(useful_cap, max(highest_prev_bid * 0.98, DAILY_SALARY * 0.65))
        elif pressure >= 0.4:
            target = min(useful_cap, max(highest_prev_bid * 0.75, DAILY_SALARY * 0.55))
        else:
            # Opponents were timid; take advantage.
            # Bid toward a higher fraction to secure water, but not beyond supply.
            target = min(useful_cap, max(DAILY_SALARY * 0.62, avg_prev_bid + 5.0))

    # Ensure we bid at least something when we need water.
    # If our HP is low, increase slightly.
    if hp <= 3.0:
        target = min(useful_cap, max(target, DAILY_SALARY * 0.7))

    # Final clamp to [0, useful_cap]
    if target < 0.0:
        target = 0.0
    if target > useful_cap:
        target = useful_cap
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    # Check yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
    # No history: fallback based on health
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    return min(my_status['budget'], DAILY_SALARY * 0.55)
